import itertools

def check_girth(n, edges):
    import collections
    adj = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for start_node in range(n):
        dist = {start_node: 0}
        parent = {start_node: None}
        queue = collections.deque([start_node])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 7:
                        return False, cycle_len
    return True, None

def is_3_colorable(n, edges):
    # Backtracking for 3-coloring
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * n
    def solve(u):
        if u == n:
            return True
        for c in range(3):
            if all(color[v] != c for v in adj[u]):
                color[u] = c
                if solve(u + 1):
                    return True
                color[u] = -1
        return False
    return solve(0)

# Let's try to build a graph with 20 vertices and 21 edges.
# A simple way to get girth 7 is to start with a cycle of length 7, 8, 9, ...
# Let's try a cycle of 20 vertices (0-1-2-...-19-0) and add one chord.
# A cycle of 20 has girth 20. Adding a chord (u, v) creates two cycles.
# The lengths will be |u-v|+1 and 20-|u-v|+1.
# We need both to be >= 7.
# |u-v|+1 >= 7 => |u-v| >= 6
# 20-|u-v|+1 >= 7 => 20-|u-v| >= 6 => |u-v| <= 14
# So if we add a chord (0, 6), the cycles are 7 and 15. Both >= 7.
# This gives 21 edges and 20 vertices.
# Let's check if it's 3-colorable.
edges = [(i, (i + 1) % 20) for i in range(20)]
edges.append((0, 6))
print(f"Girth check: {check_girth(20, edges)}")
print(f"3-colorable: {is_3_colorable(20, edges)}")
